1	// === Types ===
2	type Customer = { yearsWithMHPCO: number };
3	type Item = { type: string; cursed?: boolean; enchantment?: number };
4	type Damage = { itemType: string; amount: number };
5	type Incident = { cause: string; damages: Damage[] };
6	type QuoteStep = { op: "quote"; items: Item[] };
7	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
8	type Step = QuoteStep | ClaimStep;
9	type Scenario = { customer: Customer; steps: Step[] };
10	type Policy = { items: Item[]; remainingCap: number };
11	
12	// === Premium constants ===
13	const PROCESSING_FEE = 5;
14	const FIRST_INSURANCE_RATE = 0.1;
15	const LOYALTY_DISCOUNT_RATE = 0.2;
16	const LOYALTY_YEARS_THRESHOLD = 2;
17	const FOLLOWUP_DISCOUNT_RATE = 0.15;
18	const CURSE_RATE = 0.5;
19	const HIGH_ENCHANTMENT_RATE = 0.3;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	// === Component-block constants ===
32	const BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_PRICE = 60;
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	// === Policy / claim constants ===
37	const DEDUCTIBLE = 100;
38	const CAP_MULTIPLIER = 2;
39	const INSURANCE_VALUE_MULTIPLIER = 10;
40	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
41	const HALF_REIMBURSEMENT_RATE = 0.5;
42	
43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	const rateIfApplies = (applies: boolean, base: number, rate: number): number =>
48	  applies ? base * rate : 0;
49	
50	// === Base premium ===
51	const basePremium = (item: Item): number => {
52	  const price = BASE_PREMIUMS[item.type];
53	  if (price === undefined) throw new Error(`unknown item type: ${item.type}`);
54	  return price;
55	};
56	
57	const isHighlyEnchanted = (item: Item): boolean =>
58	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
59	
60	const itemSurcharge = (item: Item): number => {
61	  const base = basePremium(item);
62	  return rateIfApplies(item.cursed ?? false, base, CURSE_RATE)
63	       + rateIfApplies(isHighlyEnchanted(item), base, HIGH_ENCHANTMENT_RATE);
64	};
65	
66	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
67	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
68	
69	const groupBasePremium = (sameTypeItems: Item[]): number =>
70	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
71	
72	const groupByType = (items: Item[]): Item[][] => {
73	  const byType = new Map<string, Item[]>();
74	  for (const item of items) {
75	    const bucket = byType.get(item.type) ?? [];
76	    bucket.push(item);
77	    byType.set(item.type, bucket);
78	  }
79	  return [...byType.values()];
80	};
81	
82	const totalBasePremium = (items: Item[]): number =>
83	  sumBy(groupByType(items), groupBasePremium);
84	
85	// === Policy-wide premium modifiers ===
86	const isLoyal = (customer: Customer): boolean =>
87	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
88	
89	const loyaltyDiscount = (base: number, customer: Customer): number =>
90	  rateIfApplies(isLoyal(customer), base, LOYALTY_DISCOUNT_RATE);
91	
92	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
93	
94	const followupDiscount = (base: number, isFollowup: boolean): number =>
95	  rateIfApplies(isFollowup, base, FOLLOWUP_DISCOUNT_RATE);
96	
97	const perItemSurcharges = (items: Item[]): number => sumBy(items, itemSurcharge);
98	
99	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
100	  const base = totalBasePremium(items);
101	  const surcharges = perItemSurcharges(items) + firstInsuranceSurcharge(base);
102	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
103	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
104	};
105	
106	// === Insurance / cap ===
107	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
108	
109	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
110	
111	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
112	
113	// === Claim payout ===
114	const qualifiesForHalfReimbursement = (item: Item): boolean =>
115	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
116	
117	const reimbursementRate = (item: Item): number =>
118	  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;
119	
120	const applyDeductible = (amount: number): number => Math.max(0, amount - DEDUCTIBLE);
121	
122	const findInsuredItem = (items: Item[], itemType: string): Item => {
123	  const item = items.find((i) => i.type === itemType);
124	  if (item === undefined) throw new Error(`uninsured item type: ${itemType}`);
125	  return item;
126	};
127	
128	const damagePayout = (damage: Damage, items: Item[]): number => {
129	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
130	  const item = findInsuredItem(items, damage.itemType);
131	  return applyDeductible(damage.amount * reimbursementRate(item));
132	};
133	
134	// === Step handlers ===
135	const handleQuote = ({ items }: QuoteStep, customer: Customer, policies: Policy[]) => {
136	  const isFollowup = policies.length > 0;
137	  const premium = premiumForItems(items, customer, isFollowup);
138	  policies.push({ items, remainingCap: policyCap(items) });
139	  return { premium };
140	};
141	
142	const claimPayout = (damages: Damage[], policy: Policy): number => {
143	  const rawPayout = sumBy(damages, (d) => damagePayout(d, policy.items));
144	  return Math.min(Math.floor(rawPayout), policy.remainingCap);
145	};
146	
147	const handleClaim = (step: ClaimStep, policies: Policy[]) => {
148	  const policy = policies[step.policy];
149	  const payout = claimPayout(step.incident.damages, policy);
150	  policy.remainingCap -= payout;
151	  return { payout, remainingCap: policy.remainingCap };
152	};
153	
154	export const runScenario = ({ customer, steps }: Scenario): unknown => {
155	  const policies: Policy[] = [];
156	  const results = steps.map((step) =>
157	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
158	  );
159	  return { results };
160	};
